import React, { useRef } from 'react';

const STRATEGY_LABELS = {
  Standard:      { uz: 'Oddiy narx',         emoji: '💰' },
  HappyHour:     { uz: 'Baxtli soat (-20%)', emoji: '🎉' },
  LoyaltyCard:   { uz: 'Doimiy mijoz',        emoji: '⭐' },
  GroupDiscount: { uz: 'Guruh chegirma',      emoji: '👥' },
};

export default function ReceiptModal({ bill, table, onClose }) {
  const receiptRef = useRef();

  const now       = new Date();
  const receiptNo = `BP-${now.getFullYear()}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}-${bill.id.slice(0,6).toUpperCase()}`;
  const timeStr   = now.toLocaleTimeString('uz-UZ',  { hour:'2-digit', minute:'2-digit', second:'2-digit' });
  const dateStr   = now.toLocaleDateString('uz-UZ',  { day:'2-digit', month:'2-digit', year:'numeric' });
  const stratLabel = STRATEGY_LABELS[bill.strategyName] || { uz: bill.strategyName, emoji: '💳' };

  const discount  = bill.lineItems.find(l => l.amount < 0);
  const itemLines = bill.lineItems.filter(l => l.amount > 0);
  const grossSum  = itemLines.reduce((s,l) => s + l.amount, 0);
  const fiscalNo  = String(Math.floor(Math.random() * 9000) + 1000);

  function handlePrint() {
    const printWin = window.open('', '_blank', 'width=420,height=750');
    printWin.document.write(`
      <html>
        <head>
          <title>BitePlate Chek #${receiptNo}</title>
          <style>
            @import url('https://fonts.googleapis.com/css2?family=Courier+Prime:wght@400;700&display=swap');
            * { margin:0; padding:0; box-sizing:border-box; }
            body { font-family:'Courier Prime','Courier New',monospace; background:#fff; color:#111;
                   font-size:12px; padding:20px 16px; width:320px; }
            .center { text-align:center; }
            .row { display:flex; justify-content:space-between; margin-bottom:2px; }
            .bold { font-weight:700; }
            .sep { border-top:1px dashed #aaa; margin:8px 0; }
            .sep2 { border-top:2px solid #222; border-bottom:2px solid #222; margin:8px 0; padding:6px 0; }
            .red { color:#c00; }
          </style>
        </head>
        <body>${receiptRef.current.innerHTML}
          <script>window.onload=()=>{window.print();window.close();}<\/script>
        </body>
      </html>
    `);
    printWin.document.close();
  }

  return (
    <div className="modal-backdrop" style={{ alignItems: 'center', padding: '12px' }} onClick={onClose}>
      <div
        onClick={e => e.stopPropagation()}
        style={{
          background: '#0a0d19',
          border: '1px solid rgba(255,255,255,0.08)',
          borderRadius: 16,
          width: '100%',
          maxWidth: 380,
          display: 'flex',
          flexDirection: 'column',
          boxShadow: '0 40px 100px rgba(0,0,0,0.8)',
        }}
      >
        {/* Header */}
        <div style={{
          padding: '10px 14px',
          borderBottom: '1px solid rgba(255,255,255,0.07)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          flexShrink: 0,
        }}>
          <div style={{ display:'flex', alignItems:'center', gap:8 }}>
            <span style={{ fontSize:16 }}>🧾</span>
            <div>
              <div style={{ color:'#f9fafb', fontWeight:700, fontSize:13, fontFamily:'Inter,sans-serif' }}>To'lov cheki</div>
              <div style={{ color:'#10b981', fontSize:10, fontFamily:'Inter,sans-serif' }}>✓ Muvaffaqiyatli to'landi</div>
            </div>
          </div>
          <button onClick={onClose} style={{
            width:28, height:28, borderRadius:7, border:'1px solid rgba(255,255,255,0.08)',
            background:'rgba(255,255,255,0.04)', color:'#6b7280', cursor:'pointer',
            fontSize:14, display:'flex', alignItems:'center', justifyContent:'center',
          }}>✕</button>
        </div>

        {/* Receipt — scroll yo'q, to'liq ko'rinadi */}
        <div style={{ padding: '10px 12px' }}>
          <div
            ref={receiptRef}
            style={{
              fontFamily: "'Courier New', Courier, monospace",
              background: '#fafaf7',
              color: '#111',
              borderRadius: 4,
              fontSize: '10.5px',
              lineHeight: 1.45,
              boxShadow: '0 4px 20px rgba(0,0,0,0.4)',
            }}
          >
            <div style={{ padding:'8px 12px 6px' }}>

              {/* Logo */}
              <div style={{ textAlign:'center', marginBottom:4 }}>
                <div style={{ fontSize:15, fontWeight:'bold', letterSpacing:'3px' }}>BITEPLATE</div>
                <div style={{ fontSize:8.5, color:'#666' }}>Smart Restoran Boshqaruv Tizimi</div>
                <div style={{ fontSize:8.5, color:'#888' }}>+998 71 200-00-00 · Toshkent, Yunusobod</div>
              </div>

              <DashLine />

              {/* Meta */}
              <div style={{ fontSize:10 }}>
                <Row l="Sana:"  r={dateStr} bold />
                <Row l="Vaqt:"  r={timeStr} bold />
                <Row l="Stol:"  r={`№ ${table.id}`} bold />
                <Row l="Mijoz:" r={table.customerName || '—'} bold />
                <Row l="Chek №:" r={receiptNo} bold small />
              </div>

              <DashLine />

              {/* Items */}
              <div style={{ fontWeight:'bold', fontSize:8.5, color:'#444', letterSpacing:'1px', marginBottom:3 }}>
                BUYURTMA TARKIBI
              </div>
              {itemLines.map((item, i) => {
                const match = item.description.match(/^(.+?)\s+x(\d+)$/);
                const name  = match ? match[1] : item.description;
                const qty   = match ? parseInt(match[2]) : 1;
                const unit  = (item.amount / qty).toFixed(2);
                return (
                  <div key={i} style={{ display:'flex', justifyContent:'space-between', alignItems:'baseline', marginBottom:2 }}>
                    <span style={{ flex:1, paddingRight:6, fontWeight:600 }}>{name}</span>
                    <span style={{ color:'#888', fontSize:9, whiteSpace:'nowrap', marginRight:6 }}>{qty}×${unit}</span>
                    <span style={{ fontWeight:700, whiteSpace:'nowrap' }}>${item.amount.toFixed(2)}</span>
                  </div>
                );
              })}

              <DashLine />

              {/* Totals */}
              <Row l="Jami (chegirmasiz)" r={`$${grossSum.toFixed(2)}`} />
              {discount && <Row l={`Chegirma (${stratLabel.emoji})`} r={`-$${Math.abs(discount.amount).toFixed(2)}`} red />}
              <Row l="Soliq (QQS 8%)" r={`$${bill.tax.toFixed(2)}`} />
              {bill.tip > 0 && <Row l="Chayqa" r={`$${bill.tip.toFixed(2)}`} />}

              <div style={{ borderTop:'2px solid #111', borderBottom:'2px solid #111', margin:'4px 0', padding:'4px 0' }}>
                <div style={{ display:'flex', justifyContent:'space-between', fontWeight:'bold', fontSize:13 }}>
                  <span>JAMI TO'LOV:</span>
                  <span>${bill.total.toFixed(2)}</span>
                </div>
              </div>

              {bill.perGuest && bill.guestCount > 1 && (
                <div style={{ background:'#f0efe6', borderRadius:3, padding:'3px 6px', marginBottom:3, fontSize:9.5 }}>
                  <Row l={`Har kishi (${bill.guestCount}):`} r={`$${bill.perGuest.toFixed(2)}`} bold />
                </div>
              )}

              {/* Stamp */}
              <div style={{ textAlign:'center', margin:'4px 0' }}>
                <div style={{
                  display:'inline-block', border:'1.5px solid #1a7a3a',
                  borderRadius:3, padding:'3px 12px', color:'#1a7a3a',
                  fontWeight:'bold', fontSize:10, letterSpacing:'1px',
                }}>✓ TO'LOV QABUL QILINDI</div>
              </div>

              <DashLine />

              {/* Fiscal — ixcham 2 ustun */}
              <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:'1px 8px', fontSize:8.5, color:'#555' }}>
                <span>Soliq kodi: <b>123456789</b></span>
                <span>Fiskal: <b>FP-{bill.id.slice(0,8).toUpperCase()}</b></span>
                <span>Tartib: <b>{fiscalNo}</b></span>
                <span>Narx: <b>{stratLabel.uz}</b></span>
              </div>

              <DashLine />

              {/* QR + rahmat — bitta qator */}
              <div style={{ textAlign:'center', fontSize:8, color:'#999', lineHeight:1.3 }}>
                <div style={{ fontFamily:'monospace', fontSize:7.5, letterSpacing:1 }}>█▀▀▀▀▀█ ▄▄▄ █▀▀▀▀▀█</div>
                <div style={{ color:'#bbb', fontSize:7.5 }}>tekshirish.biteplate.uz/{receiptNo.slice(0,16)}…</div>
                <div style={{ fontWeight:'bold', fontSize:9.5, color:'#333', marginTop:2 }}>*** RAHMAT! YANA KELING! ***</div>
                <div style={{ fontSize:8, color:'#aaa' }}>www.biteplate.uz</div>
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div style={{
          padding: '10px 12px',
          borderTop: '1px solid rgba(255,255,255,0.07)',
          display: 'flex',
          gap: 8,
        }}>
          <button onClick={handlePrint} style={{
            flex:1, padding:'8px', borderRadius:10,
            border:'1px solid rgba(255,255,255,0.1)',
            background:'rgba(255,255,255,0.04)', color:'#9ca3af',
            cursor:'pointer', fontSize:12, fontWeight:600, fontFamily:'Inter,sans-serif',
          }}>🖨️ Chop etish</button>
          <button onClick={onClose} style={{
            flex:1, padding:'8px', borderRadius:10,
            border:'none',
            background:'linear-gradient(135deg,#6366f1,#4f46e5)', color:'#fff',
            cursor:'pointer', fontSize:12, fontWeight:700, fontFamily:'Inter,sans-serif',
          }}>✓ Yopish</button>
        </div>
      </div>
    </div>
  );
}

function DashLine() {
  return <div style={{ borderTop:'1px dashed #bbb', margin:'4px 0' }} />;
}

function Row({ l, r, bold, small, red }) {
  return (
    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'baseline', gap:6, marginBottom:1 }}>
      <span style={{ color: red ? '#c00' : '#444', flexShrink:0 }}>{l}</span>
      <span style={{
        fontWeight: bold ? 700 : 600,
        fontSize: small ? 9 : 'inherit',
        color: red ? '#c00' : '#111',
        textAlign:'right',
        wordBreak:'break-all',
      }}>{r}</span>
    </div>
  );
}
